// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig } from '../remotionShim';
import { Star } from "@remotion/shapes";
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');
const loadRoboto = makeLoadFont('Roboto');

// Library: none — native interpolate/spring for staggered layout entrances and smooth property transitions.

const { fontFamily: oswaldFamily } = loadOswald();
const { fontFamily: robotoFamily } = loadRoboto();



export type PromoAnimationProps = Record<string, any>;

const TicketComponent: React.FC<{
  width: number;
  height: number;
  color: string;
  star?: boolean;
}> = ({ width, height, color, star }) => {
  const r = height * 0.15;
  const path = `M 0 0 
                L ${width} 0 
                L ${width} ${height / 2 - r} 
                A ${r} ${r} 0 0 0 ${width} ${height / 2 + r} 
                L ${width} ${height} 
                L 0 ${height} 
                L 0 ${height / 2 + r} 
                A ${r} ${r} 0 0 0 0 ${height / 2 - r} 
                Z`;
  return (
    <div style={{ position: 'relative', width, height, transition: 'none' }}>
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} style={{ position: 'absolute', top: 0, left: 0, overflow: 'visible', transition: 'none' }}>
        <path d={path} fill={color} style={{ transition: 'none' }} />
      </svg>
      {star && (
        <div style={{ position: 'absolute', top: 0, left: 0, width, height, display: 'flex', justifyContent: 'center', alignItems: 'center', transition: 'none' }}>
           <Star points={5} innerRadius={height * 0.08} outerRadius={height * 0.2} fill="#12172B" />
        </div>
      )}
    </div>
  );
};

const TagComponent: React.FC<{
  size: number;
  color: string;
  textColor: string;
  fontFamily: string;
}> = ({ size, color, textColor, fontFamily }) => {
  const w = size;
  const h = size * 1.5;
  const path = `M ${w / 2} 0 L ${w} ${h * 0.25} L ${w} ${h} L 0 ${h} L 0 ${h * 0.25} Z`;
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} style={{ overflow: 'visible', transition: 'none' }}>
      <path d={path} fill={color} style={{ transition: 'none' }} />
      <circle cx={w / 2} cy={h * 0.15} r={w * 0.1} fill="#12172B" style={{ transition: 'none' }} />
      <text x={w / 2} y={h * 0.8} fontSize={w * 0.7} fontFamily={fontFamily} fill={textColor} textAnchor="middle" fontWeight="bold" style={{ transition: 'none' }}>£</text>
    </svg>
  );
};

const PromoAnimation: React.FC<PromoAnimationProps> = ({
  backgroundColor = "#12172B",
  transparentBackground = false,
  durationInSeconds = 7,
  counterEndValue = 25000,
  scene1Caption = "TICKETS AVAILABLE",
  ticketPrice = "59p",
  scene2Caption = "PER TICKET",
  scene3Caption = "COIN FLIPS ON TOP",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Scene 1: Grid and Counter (0 - 75)
  const gridRecede = spring({ frame: Math.max(0, frame - 75), fps, config: { damping: 15 } });
  const gridScale = interpolate(gridRecede, [0, 1], [1, 0.6]);
  const scene1Opacity = frame > 75 ? interpolate(gridRecede, [0, 1], [1, 0]) : 1;
  const gridBlur = interpolate(gridRecede, [0, 1], [0, 10]);

  const counterProgress = spring({ frame: Math.max(0, frame - 15), fps, config: { damping: 12, mass: 1, stiffness: 80 } });
  const currentCount = Math.max(0, Math.round(interpolate(counterProgress, [0, 1], [0, counterEndValue])));
  
  const cap1Opacity = frame < 20 ? 0 : interpolate(frame - 20, [0, 15], [0, 1], { extrapolateRight: 'clamp' }) * scene1Opacity;
  const cap1Y = interpolate(frame - 20, [0, 15], [20, 0], { extrapolateRight: 'clamp' });
  const counterY = interpolate(gridRecede, [0, 1], [0, -50]);

  // Scene 2: Big Ticket and Tag (75 - 130)
  const scene2In = spring({ frame: Math.max(0, frame - 75), fps, config: { damping: 14 } });
  const scene2Out = spring({ frame: Math.max(0, frame - 130), fps, config: { damping: 15 } });

  const ticketOp = frame < 75 ? 0 : interpolate(scene2In, [0, 1], [0, 1]);
  const ticketScale = interpolate(scene2In, [0, 1], [0, 1]);
  const ticketY = interpolate(scene2In, [0, 1], [200, 0]);
  const ticketRot = interpolate(scene2In, [0, 1], [15, -5]);
  const scene2X = interpolate(scene2Out, [0, 1], [0, -width * 1.5]);

  const tagSwing = spring({ frame: Math.max(0, frame - 90), fps, config: { damping: 8, stiffness: 120 } });
  const tagRot = interpolate(tagSwing, [0, 1], [-80, 0]); 
  
  const cap2Opacity = frame < 90 ? 0 : interpolate(frame - 90, [0, 15], [0, 1], { extrapolateRight: 'clamp' }) * interpolate(scene2Out, [0, 1], [1, 0]);
  const cap2Y = interpolate(frame - 90, [0, 15], [30, 0], { extrapolateRight: 'clamp' });

  // Scene 3: Coins (135 - 210)
  const scene3CapIn = spring({ frame: Math.max(0, frame - 150), fps, config: { damping: 14 } });
  const cap3Opacity = frame < 150 ? 0 : interpolate(scene3CapIn, [0, 1], [0, 1]);
  const cap3Y = interpolate(scene3CapIn, [0, 1], [30, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      {!transparentBackground && (
        <div style={{
          position: 'absolute', width: '100%', height: '100%',
          background: `radial-gradient(circle at 50% 40%, rgba(255,255,255,0.08) 0%, rgba(255,255,255,0) 60%)`,
          transition: "none"
        }} />
      )}

      {/* SCENE 1 */}
      <AbsoluteFill style={{ pointerEvents: 'none', transition: "none" }}>
        {/* Counter */}
        <div style={{ position: 'absolute', top: height * 0.15, width: '100%', textAlign: 'center', opacity: scene1Opacity, transform: `translateY(${counterY}px)`, transition: "none" }}>
          <div style={{ fontSize: 180 * s, fontWeight: 'bold', color: '#F2C14E', lineHeight: 1, fontFamily: oswaldFamily, transition: "none" }}>
            {currentCount.toLocaleString('en-US')}
          </div>
          <div style={{ fontSize: 40 * s, color: 'white', marginTop: 10 * s, opacity: cap1Opacity, transform: `translateY(${cap1Y}px)`, fontFamily: robotoFamily, fontWeight: 600, letterSpacing: 2, transition: "none" }}>
            {scene1Caption}
          </div>
        </div>

        {/* Grid */}
        <div style={{
          position: 'absolute', top: height * 0.4, width: '100%',
          display: 'flex', justifyContent: 'center',
          transform: `scale(${gridScale})`,
          opacity: scene1Opacity,
          filter: `blur(${gridBlur}px)`,
          transition: 'none'
        }}>
          <div style={{ width: 780 * s, display: 'flex', flexWrap: 'wrap', gap: `${20 * s}px`, justifyContent: 'center', transition: "none" }}>
            {Array.from({ length: 25 }).map((_, i) => {
              const row = Math.floor(i / 5);
              const col = i % 5;
              const delay = row * 2 + col * 1;
              const itemProgress = spring({ frame: Math.max(0, frame - delay), fps, config: { damping: 12 } });
              const itemY = interpolate(itemProgress, [0, 1], [150, 0]);
              const itemOp = frame < delay ? 0 : interpolate(itemProgress, [0, 1], [0, 1]);
              return (
                <div key={i} style={{ width: 140 * s, height: 80 * s, transform: `translateY(${itemY}px)`, opacity: itemOp, transition: "none" }}>
                   <TicketComponent width={140 * s} height={80 * s} color="#F2C14E" star={true} />
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>

      {/* SCENE 2 */}
      <AbsoluteFill style={{ transform: `translateX(${scene2X}px)`, pointerEvents: 'none', transition: "none" }}>
        <div style={{
          position: 'absolute', top: height * 0.45, left: '50%',
          width: 700 * s, height: 350 * s,
          marginLeft: -350 * s, marginTop: -175 * s,
          transform: `translateY(${ticketY}px) scale(${ticketScale}) rotate(${ticketRot}deg)`,
          opacity: ticketOp,
          transition: "none"
        }}>
          <TicketComponent width={700 * s} height={350 * s} color="#F2C14E" />
          <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', display: 'flex', justifyContent: 'center', alignItems: 'center', transition: "none" }}>
            <span style={{ fontSize: 160 * s, color: '#12172B', fontFamily: oswaldFamily, fontWeight: 'bold', transition: "none" }}>{ticketPrice}</span>
          </div>

          {/* Tag Assembly */}
          {(() => {
            const dx = 120 * s;
            const dy = 60 * s;
            return (
              <div style={{
                position: 'absolute', top: 175 * s, left: 700 * s - 52.5 * s, // Attach to right cutout
                transform: `rotate(${tagRot}deg)`,
                transformOrigin: `0px 0px`, // Hinge at the ticket hole
                transition: 'none'
              }}>
                <svg style={{ position: 'absolute', top: 0, left: 0, width: dx + 20 * s, height: dy + 20 * s, overflow: 'visible', transition: "none" }}>
                  <path d={`M 0 0 Q ${dx * 0.3} ${dy * 0.8} ${dx} ${dy}`} fill="none" stroke="white" strokeWidth={6 * s} style={{ transition: "none" }} />
                </svg>
                <div style={{ position: 'absolute', left: dx - 50 * s, top: dy - 22.5 * s, transition: "none" }}>
                  <TagComponent size={100 * s} color="#F2C14E" textColor="#12172B" fontFamily={oswaldFamily} />
                </div>
              </div>
            );
          })()}
        </div>

        <div style={{ position: 'absolute', top: height * 0.7, width: '100%', textAlign: 'center', opacity: cap2Opacity, transform: `translateY(${cap2Y}px)`, transition: "none" }}>
          <div style={{ fontSize: 50 * s, color: 'white', fontFamily: robotoFamily, fontWeight: 600, letterSpacing: 2, transition: "none" }}>
            {scene2Caption}
          </div>
        </div>
      </AbsoluteFill>

      {/* SCENE 3 */}
      <AbsoluteFill style={{ pointerEvents: 'none', transition: "none" }}>
        <div style={{ position: 'absolute', top: height * 0.35, width: '100%', textAlign: 'center', opacity: cap3Opacity, transform: `translateY(${cap3Y}px)`, transition: "none" }}>
          <div style={{ fontSize: 50 * s, color: 'white', fontFamily: robotoFamily, fontWeight: 600, letterSpacing: 2, transition: "none" }}>
            {scene3Caption}
          </div>
        </div>

        <div style={{ position: 'absolute', top: height * 0.55, width: '100%', display: 'flex', justifyContent: 'center', transition: "none" }}>
          <div style={{ width: 800 * s, display: 'flex', justifyContent: 'space-between', transition: "none" }}>
            {[0, 1, 2].map((i) => {
              const delay = 135 + i * 8;
              const flip = spring({ frame: Math.max(0, frame - delay), fps, config: { damping: 12, mass: 0.8 } });
              const yPos = interpolate(flip, [0, 1], [-800, 0]);
              const angle = interpolate(flip, [0, 1], [Math.PI * 4, 0]);
              const scaleY = Math.cos(angle);
              
              const coinOp = frame < delay ? 0 : 1;
              const coinSize = 220 * s;

              const rippleDelay = delay + 22;
              const rippleProgress = spring({ frame: Math.max(0, frame - rippleDelay), fps, config: { damping: 20, mass: 0.5 } });
              const rippleScale = interpolate(rippleProgress, [0, 1], [0.5, 1.8]);
              const rippleOp = frame < rippleDelay ? 0 : interpolate(rippleProgress, [0, 1], [1, 0]);

              const badgeDelay = delay + 25;
              const badgeProgress = spring({ frame: Math.max(0, frame - badgeDelay), fps, config: { damping: 10 } });
              const badgeScale = interpolate(badgeProgress, [0, 1], [0, 1]);
              const badgeOp = frame < badgeDelay ? 0 : 1;

              const shadowOp = frame < delay ? 0 : interpolate(flip, [0, 1], [0, 0.4]);
              const shadowScale = interpolate(flip, [0, 1], [0.2, 1]);

              return (
                <div key={i} style={{ position: 'relative', width: coinSize, height: coinSize, transition: "none" }}>
                   {/* Ripple */}
                   <div style={{
                     position: 'absolute', top: '50%', left: '50%',
                     width: coinSize, height: coinSize,
                     marginLeft: -coinSize / 2, marginTop: -coinSize / 2,
                     borderRadius: '50%', border: `${4 * s}px solid #F2C14E`,
                     transform: `scale(${rippleScale})`, opacity: rippleOp,
                     transition: 'none'
                   }} />

                   {/* Shadow */}
                   <div style={{
                     position: 'absolute', bottom: -20 * s, left: '50%',
                     width: coinSize * 0.8, height: coinSize * 0.2,
                     marginLeft: -coinSize * 0.4,
                     background: 'rgba(0,0,0,0.4)', borderRadius: '50%',
                     transform: `scale(${shadowScale})`,
                     opacity: shadowOp,
                     filter: `blur(${5 * s}px)`,
                     transition: 'none'
                   }} />

                   {/* Coin */}
                   <div style={{
                     position: 'absolute', top: 0, left: 0, width: coinSize, height: coinSize,
                     transform: `translateY(${yPos}px) scaleY(${scaleY})`, opacity: coinOp,
                     transition: 'none'
                   }}>
                     <svg width={coinSize} height={coinSize} viewBox="0 0 100 100" style={{ transition: "none" }}>
                       <circle cx="50" cy="50" r="50" fill="#C89C33" style={{ transition: "none" }} />
                       <circle cx="50" cy="50" r="42" fill="#F2C14E" style={{ transition: "none" }} />
                       <text x="50" y="68" fontSize="48" fontFamily={oswaldFamily} fill="#C89C33" textAnchor="middle" fontWeight="bold" style={{ transition: "none" }}>£</text>
                     </svg>
                   </div>

                   {/* Badge */}
                   <div style={{
                     position: 'absolute', top: -10 * s, right: -20 * s,
                     width: 60 * s, height: 60 * s, borderRadius: '50%',
                     background: '#F2C14E',
                     transform: `scale(${badgeScale})`, opacity: badgeOp,
                     display: 'flex', justifyContent: 'center', alignItems: 'center',
                     boxShadow: `0 ${4 * s}px ${8 * s}px rgba(0,0,0,0.3)`,
                     transition: 'none'
                   }}>
                     <span style={{ color: '#12172B', fontSize: 32 * s, fontWeight: 'bold', fontFamily: oswaldFamily, marginTop: -2 * s, transition: "none" }}>+£</span>
                   </div>
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default PromoAnimation;